package com.cpf.batch.worker; import com.cpf.batch.api.*; import com.cpf.batch.runtime.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.context.annotation.*; import org.springframework.boot.context.properties.EnableConfigurationProperties;
@EnableConfigurationProperties(WorkerOperationalProperties.class) @SpringBootApplication(scanBasePackages="com.cpf.batch.worker") @Import({RuntimeCommonConfiguration.class,BatDataSourceConfiguration.class}) public class BatchWorkerApplication { public static void main(String[]a){SpringApplication.run(BatchWorkerApplication.class,a);} @Bean JobPackReporter jobPackReporter(com.cpf.batch.runtime.JobPackCatalog c,org.springframework.web.client.RestClient.Builder b,
 @org.springframework.beans.factory.annotation.Value("${cpf.batch.control.base-url:${CPF_BATCH_CONTROL_BASE_URL:http://127.0.0.1:8180}}") String url){return new JobPackReporter(c,b,url);}
 @Bean RuntimeRegistration runtimeRegistration(){return RuntimeIdentityFactory.fromEnvironment(RuntimeRole.WORKER,"cpf-batch-worker",8182);} }
